"""Nombres et calculs : données et exercices originaux de Quatrième, programme 2026."""
from modele import chapitre,E,Q,tableau

chapitre(1,'relatifs','Multiplier et diviser des nombres relatifs','1 · Nombres et calculs',
'Produits · Quotients · Enchaînements · Programmes de calcul',
['Multiplier deux nombres relatifs et justifier la règle des signes.','Diviser des relatifs et enchaîner les quatre opérations.','Nommer un calcul et traduire un programme de calcul.'],
['Addition, soustraction et droite graduée des nombres relatifs (Cinquième).'],[
r'''\essSection{1}{Construire le produit}
\begin{definition}Deux nombres sont opposés si leur somme vaut 0 : l’opposé de $a$ est $-a$. Soustraire un nombre revient à ajouter son opposé : $a-b=a+(-b)$. Sur une droite graduée, deux nombres opposés sont symétriques par rapport à l’origine.\end{definition}
\begin{propriete}[Un seul facteur négatif]Le produit d’un nombre positif et d’un nombre négatif est négatif. Par exemple $3\times(-5)=(-5)+(-5)+(-5)=-15$, et $(-5)\times3=3\times(-5)$ car l’ordre des facteurs ne change pas un produit.\end{propriete}
\begin{propriete}[Deux facteurs négatifs]Par distributivité, $(-7)\times(-4)+(-7)\times4=(-7)\times(-4+4)=0$. Donc $(-7)\times(-4)$ est l’opposé de $(-7)\times4=-28$ : il vaut 28. Règle des signes : le produit de deux nombres non nuls est positif si leurs signes sont identiques, négatif sinon. Multiplier par $-1$ donne l’opposé.\end{propriete}
\begin{exemple}Pour plusieurs facteurs non nuls, on compte les facteurs négatifs : $(-2)\times(-3)\times(-4)=-24$, car il y en a trois, nombre impair. Un produit qui contient un facteur nul est nul.\end{exemple}
\begin{attention}Deux signes « moins » n’ont pas toujours le même rôle. Dans $-4-3$, on soustrait 3 : le résultat est $-7$. Dans $(-4)\times(-3)$, on multiplie deux nombres négatifs : le résultat est 12.\end{attention}''',
r'''\essSection{2}{Diviser et enchaîner}
\begin{propriete}Pour $b\ne0$, le quotient $a:b$, noté aussi $\frac ab$, est le nombre qui, multiplié par $b$, donne $a$. Ainsi $(-12):4=-3$ car $(-3)\times4=-12$ : la règle des signes d’un quotient est celle du produit. On ne divise jamais par zéro.\end{propriete}
\begin{savoirfaire}[Une ligne par étape]Calculer d’abord les parenthèses, puis les produits et quotients de gauche à droite, enfin les sommes et différences de gauche à droite. Réécrire les parties inchangées pour conserver la structure.\end{savoirfaire}
\begin{exemple}$(-3)+(-4)\times7=(-3)+(-28)=-31$ et $-5\times(2-7)=-5\times(-5)=25$. Dans $6-2\times(-3+7)=6-8=-2$, la parenthèse est calculée d’abord.\end{exemple}
\begin{definition}[Nommer un calcul]Un calcul porte le nom de la dernière opération effectuée : $(-3)+(-4)\times7$ est une somme, $-5\times(2-7)$ est un produit. Le programme « choisir $-2$, ajouter 6, multiplier par $-3$ » s’écrit en une seule expression $(-2+6)\times(-3)$ : c’est un produit, qui vaut $-12$.\end{definition}
\begin{savoirfaire}[Contrôler]Prévoir le signe, estimer l’ordre de grandeur, puis vérifier par une opération inverse. Dans un problème, préciser le sens du signe et l’unité : $-8$ euros représente une baisse de 8 euros.\end{savoirfaire}'''],[
E('Un produit positif',r"Calculer $(-7)\times(-6)$.",r"Les deux facteurs ont le même signe, donc le résultat est positif. $7\times6=42$, ainsi $(-7)\times(-6)=\res{42}$.","Déterminer le signe avant de multiplier.","assert (-7)*(-6)==42"),
E('Un produit négatif',r"Calculer $2{,}4\times(-5)$.",r"Les signes sont différents : le produit est négatif. $2{,}4\times5=12$, donc le résultat est $\res{-12}$.","Séparer signe et distance à zéro.","assert Rational('2.4')*(-5)==-12"),
E('Un quotient',r"Calculer $(-54):(-9)$ et $18:(-4)$.",r"Le premier quotient est positif : $54:9=\res6$. Le second est négatif : $18:4=4{,}5$, donc $\res{-4{,}5}$. Contrôle : $(-4{,}5)\times(-4)=18$.","Appliquer la règle des signes à chaque quotient.","assert Rational(-54,-9)==6 and Rational(18,-4)==Rational('-4.5')"),
E('Opposé ou produit',r"Calculer $-8-(-3)$ et $(-8)\times(-3)$.",r"Soustraire $-3$ revient à ajouter 3 : $-8+3=\res{-5}$. Pour le produit, deux facteurs négatifs donnent un résultat positif : $\res{24}$.","Identifier l’opération écrite entre les nombres.","assert -8-(-3)==-5 and (-8)*(-3)==24"),
E('Nommer puis calculer',r"Dire si chaque calcul est une somme, un produit ou un quotient, puis le calculer : $A=(-3)+(-4)\times7$ ; $B=-5\times(2-7)$ ; $C=[12-(-6)]:(-3)$.",r"Dans A, la dernière opération est l’addition : A est une $\res{\text{somme}}$, $A=-3-28=\res{-31}$. B est un $\res{\text{produit}}$ : $B=-5\times(-5)=\res{25}$. C est un $\res{\text{quotient}}$ : $C=18:(-3)=\res{-6}$.","Repérer l’opération effectuée en dernier.","assert -3+(-4)*7==-31 and -5*(2-7)==25 and Rational(12-(-6),-3)==-6"),
E('Compter les signes',r"Sans effectuer les multiplications, donner le signe de $(-2)\times5\times(-3)\times(-7)$, puis calculer.",r"Il y a trois facteurs négatifs : le produit est négatif. Les distances à zéro donnent $2\times5\times3\times7=210$. Résultat : $\res{-210}$.","Compter les facteurs négatifs non nuls.","assert (-2)*5*(-3)*(-7)==-210"),
E('Respecter les priorités',r"Calculer $A=14-3\times(-2)$ et $B=(14-3)\times(-2)$.",r"$A=14-(-6)=\res{20}$. Dans $B$, les parenthèses passent d’abord : $B=11\times(-2)=\res{-22}$.","Ne pas déplacer une parenthèse.","assert 14-3*(-2)==20 and (14-3)*(-2)==-22"),
E('Une expression imbriquée',r"Calculer $18:[-2\times(5-8)]$.",r"$5-8=-3$, puis $-2\times(-3)=6$. Le quotient vaut donc $18:6=\res3$. Le crochet entier doit être calculé avant la division.","Commencer par la parenthèse la plus intérieure.","assert Rational(18,(-2)*(5-8))==3"),
E('Des multiplications à trou',r"Compléter : $(-6)\times\ldots=42$ ; $\ldots\times(-2{,}5)=-10$ ; $7\times\ldots=-3$.",r"Le nombre cherché est un quotient. $42:(-6)=\res{-7}$ ; $(-10):(-2{,}5)=\res4$ ; $(-3):7=\res{-\frac37}$. Contrôle : $7\times\left(-\frac37\right)=-3$, par définition du quotient.","Retrouver un facteur en divisant.","assert Rational(42,-6)==-7 and Rational(-10)/Rational('-2.5')==4 and 7*Rational(-3,7)==-3"),
E('Une erreur de calcul',r"Nora écrit $24:(-6)\times2=24:(-12)=-2$. Corriger.",r"Produits et quotients ont la même priorité et se calculent de gauche à droite : $24:(-6)=-4$, puis $-4\times2=\res{-8}$. Nora a ajouté des parenthèses absentes.","Conserver l’ordre de gauche à droite.","assert Rational(24,-6)*2==-8 and Rational(24,-12)==-2"),
E('Évolution de température',r"À midi, il fait $3\,^\circ$C. Pendant 5 heures, la température varie de $-1{,}6\,^\circ$C par heure. Quelle température obtient-on ?",r"La variation totale est $5\times(-1{,}6)=-8\,^\circ$C. On l’ajoute à la température initiale : $3-8=\res{-5\,^\circ\mathrm C}$. Une variation négative représente une baisse.","Additionner la variation à la valeur initiale.","assert 3+5*Rational('-1.6')==-5"),
E('Un programme de calcul',r"Programme : choisir un nombre ; le multiplier par $-3$ ; ajouter 7 ; multiplier le résultat par $-2$."+Q(r"Appliquer ce programme au nombre $-4$.",r"Écrire ce calcul en une seule expression.",r"Cette expression est-elle une somme ou un produit ?"),r"On obtient successivement $(-4)\times(-3)=12$, puis $12+7=19$, puis $19\times(-2)=\res{-38}$. L’expression est $\res{[(-4)\times(-3)+7]\times(-2)}$ : la dernière opération est une multiplication, c’est un $\res{\text{produit}}$. Les crochets traduisent l’ordre des étapes.","Écrire chaque étape, puis les emboîter.","assert ((-4)*(-3)+7)*(-2)==-38"),
E('Un nombre inconnu',r"Quel nombre faut-il multiplier par $-2{,}5$ pour obtenir 15 ? Vérifier.",r"On effectue l’opération inverse : $15:(-2{,}5)=\res{-6}$. Vérification : $(-2{,}5)\times(-6)=15$. Le signe négatif est nécessaire pour obtenir un produit positif.","Utiliser le quotient pour retrouver un facteur.","assert Rational(15,1)/Rational('-2.5')==-6"),
E('La machine à signes',r"Le produit de 19 nombres négatifs non nuls est-il positif ? Que devient son signe si l’on remplace un facteur par son opposé, puis si l’on remplace un facteur par zéro ?",r"19 est impair : le produit est négatif. Remplacer un facteur par son opposé change une seule fois le signe, donc le produit devient positif. Avec un facteur nul, tout le produit vaut $\res0$ : on ne lui applique plus la règle pair-impair.","Traiter le cas nul séparément.","assert (-1)**19==-1 and (-1)**18==1 and 0*(-1)**18==0"),
E('Un calcul à contrôler',r"Calculer $C=-3[4-2(-5+8)]+12:(-4)$. Donner un contrôle du signe final.",r"$-5+8=3$, puis $4-2\times3=-2$. Le premier terme vaut $(-3)\times(-2)=6$ et le second $-3$. Donc $C=6-3=\res3$. Le premier terme positif dépasse en valeur le second, négatif : le signe positif est cohérent.","Calculer séparément les deux termes principaux.","assert -3*(4-2*(-5+8))+Rational(12,-4)==3")
],reperes=['Produit de deux relatifs et règle des signes','Quotients et multiplications à trou','Priorités et enchaînements d’opérations','Vocabulaire et programmes de calcul'],deco='calcul')

chapitre(2,'rationnels','Nombres rationnels et fractions','1 · Nombres et calculs',
'Simplifier · Multiplier · Inverser · Diviser',
['Simplifier une fraction et exprimer l’opposé d’un nombre rationnel.','Multiplier et diviser des fractions en utilisant l’inverse.','Résoudre des problèmes de fraction d’une quantité ou d’un reste.'],
['Fractions égales, comparaison, sommes et différences de fractions (Cinquième).','Règles des signes du chapitre 1.'],[
r'''\essSection{1}{Des quotients d’entiers}
\begin{definition}Une fraction $\frac ab$ est le quotient de deux entiers $a$ et $b$, avec $b\ne0$ : c’est le nombre qui, multiplié par $b$, donne $a$, donc $b\times\frac ab=a$. Un nombre rationnel est un nombre égal au quotient de deux entiers relatifs. Il peut être entier ($\frac{12}4=3$), décimal ($\frac78=0{,}875$) ou ni l’un ni l’autre ($\frac13$).\end{definition}
\begin{propriete}[Simplifier]On ne change pas un quotient en multipliant ou en divisant son numérateur et son dénominateur par un même nombre non nul : $\frac{42}{56}=\frac{3\times14}{4\times14}=\frac34$. Simplifier, c’est diviser les deux termes par un diviseur commun.\end{propriete}
\begin{propriete}[Opposé d’un rationnel]$\frac{-a}{b}=\frac{a}{-b}=-\frac ab$. Par exemple $\frac43+\frac{-4}3=\frac{4-4}3=0$ : $\frac{-4}3$ est donc l’opposé de $\frac43$. On écrit en général le dénominateur positif.\end{propriete}
\begin{exemple}[Rappel de Cinquième]Pour additionner, soustraire ou comparer, on écrit les fractions avec un même dénominateur positif : $\frac34-\frac56=\frac9{12}-\frac{10}{12}=-\frac1{12}$. Ainsi $\frac34<\frac56$.\end{exemple}''',
r'''\essSection{2}{Multiplier, inverser, diviser}
\begin{propriete}Pour $b\ne0$ et $d\ne0$ : $\frac ab\times\frac cd=\frac{a\times c}{b\times d}$. Prendre une fraction d’un nombre, d’une quantité ou d’une fraction revient à multiplier : les $\frac23$ de $\frac45$ valent $\frac23\times\frac45=\frac8{15}$.\end{propriete}
@FIG:cours-fraction-fraction@
\begin{definition}L’inverse d’un nombre $a$ non nul est le nombre qui, multiplié par $a$, donne 1. On le note $\frac1a$ : c’est le quotient de 1 par $a$. Si $a\ne0$ et $b\ne0$, l’inverse de $\frac ab$ est $\frac ba$. Zéro n’a pas d’inverse.\end{definition}
\begin{propriete}Diviser par un nombre non nul revient à multiplier par son inverse : $\frac ab:\frac cd=\frac ab\times\frac dc$, avec $b$, $c$, $d$ non nuls. Exemple : $\frac54:\frac23=\frac54\times\frac32=\frac{15}8$.\end{propriete}
\begin{attention}$\frac12+\frac13=\frac56$ et non $\frac25$ : on n’additionne pas les dénominateurs. Les priorités s’appliquent aussi aux fractions : dans $\frac56-\frac23\times\frac94$, le produit passe d’abord.\end{attention}'''],[
E('Des fractions égales',r"Simplifier $\frac{42}{56}$ et $\frac{36}{-48}$, puis compléter $\frac{-3}{4}=\frac{\,?\,}{20}$.",r"$42$ et $56$ sont dans la table de 14 : $\frac{42}{56}=\res{\frac34}$. De même $\frac{36}{-48}=\frac{3}{-4}=\res{-\frac34}$. Enfin on multiplie les deux termes de $\frac{-3}4$ par 5 : $\res{\frac{-15}{20}}$.","Agir de la même façon sur les deux termes.","assert Rational(42,56)==Rational(3,4) and Rational(36,-48)==Rational(-3,4) and Rational(-3,4)==Rational(-15,20)"),
E('Entier, décimal ou non',r"Les nombres $\frac{12}4$, $\frac7{20}$, $\frac13$ et $\frac{-18}6$ sont rationnels. Lesquels sont entiers ? décimaux ?",r"$\frac{12}4=3$ et $\frac{-18}6=-3$ sont $\res{\text{entiers}}$, donc aussi décimaux. $\frac7{20}=\res{0{,}35}$ est décimal non entier. $\frac13=0{,}333\ldots$ n’est $\res{\text{ni entier ni décimal}}$ : la division ne s’arrête jamais.","Effectuer la division du numérateur par le dénominateur.","assert Rational(12,4)==3 and Rational(-18,6)==-3 and Rational(7,20)==Rational('0.35') and factorint(Rational(1,3).q)=={3:1}"),
E('L’opposé d’un quotient',r"Calculer $\frac57+\frac{-5}7$. Que peut-on en déduire ? Écrire ensuite $\frac3{-8}$ avec un dénominateur positif.",r"$\frac57+\frac{-5}7=\frac07=\res0$ : les deux nombres sont opposés, donc $\frac{-5}7=-\frac57$. En multipliant les deux termes par $-1$ : $\frac3{-8}=\res{\frac{-3}8=-\frac38}$.","Utiliser la définition de l’opposé.","assert Rational(5,7)+Rational(-5,7)==0 and Rational(3,-8)==Rational(-3,8)"),
E('Additionner',r"Calculer $\frac34-\frac56$.",r"Le dénominateur commun 12 donne $\frac9{12}-\frac{10}{12}=\res{-\frac1{12}}$. Le résultat négatif est cohérent puisque $\frac34<\frac56$.","Réduire au même dénominateur.","assert Rational(3,4)-Rational(5,6)==Rational(-1,12)"),
E('Multiplier',r"Calculer $\frac{-4}{7}\times\frac{21}{10}$.",r"Le résultat est négatif. On simplifie avant de multiplier : $\frac{4\times21}{7\times10}=\frac{4\times3\times7}{7\times2\times5}=\frac65$. Donc le produit vaut $\res{-\frac65}$.","Décomposer pour simplifier avant de multiplier.","assert Rational(-4,7)*Rational(21,10)==Rational(-6,5)"),
E('Une fraction d’une fraction',r"Un rectangle est partagé en 4 colonnes et 3 lignes de cases identiques. On colorie les $\frac34$ du rectangle, puis les $\frac23$ de la partie coloriée. Quelle fraction du rectangle représente cette seconde partie ? Écrire le calcul.",r"Les $\frac34$ du rectangle sont 3 colonnes, soit 9 cases sur 12. Les $\frac23$ de cette partie sont 2 lignes de ces 3 colonnes, soit 6 cases. Le calcul est $\frac23\times\frac34=\frac6{12}=\res{\frac12}$ du rectangle.","Représenter puis multiplier les fractions.","assert Rational(2,3)*Rational(3,4)==Rational(6,12)==Rational(1,2)",figure='fraction-rectangle'),
E('Trouver un inverse',r"Donner l’inverse de $-\frac53$, puis calculer $\frac23:\left(-\frac53\right)$.",r"$\left(-\frac53\right)\times\left(-\frac35\right)=1$, donc l’inverse est $\res{-\frac35}$. Le quotient vaut $\frac23\times\left(-\frac35\right)=\res{-\frac25}$. Seul le diviseur est remplacé par son inverse.","Transformer la division en multiplication.","assert 1/Rational(-5,3)==Rational(-3,5) and Rational(2,3)/Rational(-5,3)==Rational(-2,5)"),
E('Opposé ou inverse',r"Donner l’opposé et l’inverse de 4, de $-\frac16$ et de $0{,}25$.",r"Opposés : $\res{-4}$, $\res{\frac16}$ et $\res{-0{,}25}$, car chaque somme vaut 0. Inverses : $\res{\frac14}$, $\res{-6}$ et $\res4$, car chaque produit vaut 1. L’inverse d’un nombre négatif est négatif.","Somme nulle pour l’opposé, produit égal à 1 pour l’inverse.","assert 4*Rational(1,4)==1 and Rational(-1,6)*(-6)==1 and Rational('0.25')*4==1 and Rational(-1,6)+Rational(1,6)==0"),
E('Un calcul enchaîné',r"Calculer $\frac56-\frac23\times\frac94$.",r"La multiplication est prioritaire : $\frac23\times\frac94=\frac{18}{12}=\frac32$. Donc $\frac56-\frac32=\frac56-\frac96=\res{-\frac23}$.","Respecter la priorité du produit.","assert Rational(5,6)-Rational(2,3)*Rational(9,4)==Rational(-2,3)"),
E('Diviser une somme',r"Calculer $\left(\frac34-\frac12\right):\frac58$.",r"La parenthèse vaut $\frac14$. On multiplie ensuite par l’inverse $\frac85$ : $\frac14\times\frac85=\res{\frac25}$. On peut vérifier que $\frac25\times\frac58=\frac14$.","Terminer la parenthèse avant d’inverser le diviseur.","assert (Rational(3,4)-Rational(1,2))/Rational(5,8)==Rational(2,5)"),
E('Qui a bu le plus ?',r"Inès boit les $\frac25$ d’une bouteille de jus. Hugo boit ensuite les $\frac23$ de ce qui reste. Qui a bu le plus ? Quelle fraction de la bouteille reste-t-il ?",r"Après Inès, il reste $1-\frac25=\frac35$ de la bouteille. Hugo boit $\frac23\times\frac35=\frac25$ de la bouteille : $\res{\text{ils ont bu autant}}$. Il reste $1-\frac25-\frac25=\res{\frac15}$ de la bouteille. La fraction de Hugo porte sur le reste, pas sur la bouteille entière.","Exprimer chaque part comme fraction de la bouteille entière.","assert Rational(2,3)*(1-Rational(2,5))==Rational(2,5) and 1-2*Rational(2,5)==Rational(1,5)"),
E('Lire une portion du reste',r"Un réservoir contient 60 L. On utilise $\frac25$ de son contenu, puis $\frac13$ de ce qui reste. Combien de litres reste-t-il ?",r"Après le premier usage, il reste $\left(1-\frac25\right)\times60=36$ L. On utilise ensuite $\frac13\times36=12$ L, donc il reste $\res{24\ \mathrm L}$. La seconde fraction ne porte pas sur les 60 L initiaux.","Préciser à quelle quantité s’applique chaque fraction.","assert 60*(1-Rational(2,5))*(1-Rational(1,3))==24"),
E('Retrouver une quantité',r"Les $\frac7{12}$ d’un budget valent 175 euros. Quel est le budget total et quelle somme n’a pas encore été utilisée ?",r"Si $B$ est le budget, $\frac7{12}\times B=175$. Donc $B=175:\frac7{12}=175\times\frac{12}7=\res{300}$ euros. La part restante vaut $300-175=\res{125}$ euros. Contrôle : $\frac7{12}\times300=175$.","Diviser par la fraction connue.","assert Rational(175)/Rational(7,12)==300 and 300-175==125"),
E('Une affirmation à discuter',r"Tom affirme : « Diviser un nombre positif par une fraction le rend toujours plus petit. » Donner un contre-exemple et préciser quand le quotient devient plus grand.",r"$6:\frac12=6\times2=12>6$ est un $\res{\text{contre-exemple}}$. Pour un nombre positif, diviser par un nombre strictement compris entre 0 et 1 revient à multiplier par son inverse, supérieur à 1 : le quotient augmente. Diviser par un nombre supérieur à 1 le diminue.","Tester une fraction comprise entre 0 et 1.","assert 6/Rational(1,2)==12>6 and 6/Rational(3,2)==4<6"),
E('Trois parts successives',r"Une somme est partagée : Lina reçoit $\frac14$ du total, Sami $\frac23$ du reste et Zoé les 36 euros restants. Trouver le total et les deux premières parts.",r"Après Lina, il reste $\frac34$ du total. Après Sami, il reste $\frac13$ de ce reste, soit $\frac13\times\frac34=\frac14$ du total. Donc le total vaut $36\times4=\res{144}$ euros. Lina reçoit $\res{36}$ euros, Sami $\frac23\times108=\res{72}$ euros. Contrôle : $36+72+36=144$.","Exprimer le reste final comme fraction du total.","assert Rational(1,3)*Rational(3,4)==Rational(1,4) and 36+72+36==144")
],reperes=['Simplifier et écrire un rationnel','Opposé, inverse et quotients','Produits et fractions d’une quantité','Enchaînements et problèmes de partage'],deco='calcul')

chapitre(3,'puissances','Puissances d’exposant positif','1 · Nombres et calculs',
'Produits répétés · Puissances de dix · Règles de calcul',
['Définir et calculer une puissance d’exposant entier positif.','Multiplier des puissances d’un même nombre ou de même exposant.','Résoudre des problèmes de répétition et de grands nombres.'],
['Carrés et cubes (Cinquième), produits de nombres relatifs.'],[
r'''\essSection{1}{Une écriture des produits répétés}
\begin{definition}Pour un nombre $a$ et un entier $n\ge1$, $a^n$ désigne le produit de $n$ facteurs égaux à $a$ : $a^n=a\times a\times\cdots\times a$. On lit « $a$ exposant $n$ ». Ainsi $3^4=3\times3\times3\times3=81$ et $a^1=a$. Par convention, $a^0=1$ pour $a$ non nul.\end{definition}
\begin{exemple}$(-2)^4=16$, car quatre facteurs négatifs donnent un produit positif, tandis que $-2^4=-16$ : la puissance porte seulement sur 2. De même $(-3)^3=-27$.\end{exemple}
\begin{definition}[Puissances de dix]Pour $n\ge1$, $10^n$ s’écrit 1 suivi de $n$ zéros : $10^6=1\,000\,000$. Multiplier un nombre par $10^n$ décale chacun de ses chiffres de $n$ rangs vers la gauche. Les préfixes des unités correspondent à des puissances de dix :\end{definition}
\begin{center}\renewcommand{\arraystretch}{1.35}\begin{tabular}{c|cccccc}\toprule
Préfixe & nano & micro & milli & kilo & méga & giga\\\midrule
Facteur & $\frac1{10^9}$ & $\frac1{10^6}$ & $\frac1{10^3}$ & $10^3$ & $10^6$ & $10^9$\\\bottomrule
\end{tabular}\end{center}
\begin{attention}L’exposant compte des facteurs : $5^3=125$, alors que $5\times3=15$. Les exposants négatifs et l’écriture scientifique seront étudiés en Troisième.\end{attention}''',
r'''\essSection{2}{Calculer avec des puissances}
\begin{propriete}[Puissances d’un même nombre]Pour des entiers naturels $m$ et $n$ : $a^m\times a^n=a^{m+n}$. Exemple générique : $2^3\times2^4=(2\times2\times2)\times(2\times2\times2\times2)=2^7$ ; on compte $3+4=7$ facteurs.\end{propriete}
\begin{propriete}[Puissances de même exposant]Pour un entier naturel $n$ : $a^n\times b^n=(a\times b)^n$. Exemple : $2^3\times5^3=(2\times5)\times(2\times5)\times(2\times5)=10^3$ ; on regroupe les facteurs par paires.\end{propriete}
\begin{exemple}$10^4\times10^3=10^7$ et $4^5\times25^5=100^5=10^{10}$. Pour comparer $3\times10^5$ et $25\times10^4=2{,}5\times10^5$, on utilise la même puissance de 10 : le premier est le plus grand.\end{exemple}
\begin{attention}Une somme ne se traite pas comme un produit : $2^3+2^4=8+16=24$, alors que $2^3\times2^4=2^7=128$. Le produit $2^3\times3^2$ ne s’écrit pas avec une seule puissance : les bases et les exposants diffèrent.\end{attention}
\begin{savoirfaire}[Revenir à la définition]En cas de doute, écrire tous les facteurs et les compter. Les deux propriétés résument ce comptage ; elles ne s’appliquent qu’à des produits.\end{savoirfaire}'''],[
E('Déplier une puissance',r"Écrire $5^3$ comme produit et le calculer.",r"$5^3=5\times5\times5=\res{125}$. Il y a trois facteurs 5 ; $5\times3$ donnerait 15 et ne représente pas cette puissance.","Compter les facteurs.","assert 5**3==125"),
E('Attention aux parenthèses',r"Calculer $(-3)^2$, $-3^2$ et $(-3)^3$.",r"$(-3)^2=(-3)\times(-3)=\res9$. $-3^2=-(3\times3)=\res{-9}$. Enfin $(-3)^3=\res{-27}$, car trois facteurs négatifs donnent un produit négatif.","Repérer la base exacte de la puissance.","assert (-3)**2==9 and -(3**2)==-9 and (-3)**3==-27"),
E('Puissances de dix',r"Donner l’écriture décimale de $10^5$, $10^1$ et $10^0$.",r"$10^5=\res{100\,000}$ : 1 suivi de cinq zéros. $10^1=\res{10}$ et, par convention, $10^0=\res1$.","Compter les zéros donnés par l’exposant.","assert 10**5==100000 and 10**1==10 and 10**0==1"),
E('Écrire une puissance',r"Écrire sous la forme d’une puissance : $3\times3\times3\times3\times3$ ; $(-2)\times(-2)\times(-2)$ ; $7$.",r"On compte les facteurs égaux : $\res{3^5}$, $\res{(-2)^3}$ et $\res{7^1}$. Les parenthèses de $(-2)^3$ indiquent que le facteur répété est $-2$.","Compter les facteurs identiques.","assert 3**5==3*3*3*3*3 and (-2)**3==(-2)*(-2)*(-2) and 7**1==7"),
E('Lire un préfixe',r"Convertir 6 km en mètres, 3 Go (gigaoctets) en octets et 4 mg en grammes.",r"Kilo signifie $10^3$ : $6$ km $=\res{6\,000\ \mathrm m}$. Giga signifie $10^9$ : 3 Go $=\res{3\times10^9}$ octets, soit trois milliards. Milli signifie $\frac1{10^3}$ : 4 mg $=\frac4{1\,000}$ g $=\res{0{,}004\ \mathrm g}$.","Remplacer chaque préfixe par son facteur.","assert 6*10**3==6000 and 3*10**9==3000000000 and Rational(4,10**3)==Rational('0.004')"),
E('Même nombre',r"Écrire sous la forme d’une seule puissance : $2^3\times2^5$ ; $7\times7^4$ ; $10^6\times10^2\times10$.",r"On additionne les nombres de facteurs : $\res{2^8}$ ; $7=7^1$ donne $\res{7^5}$ ; $6+2+1=9$ donne $\res{10^9}$.","Utiliser $a^m\times a^n=a^{m+n}$.","assert 2**3*2**5==2**8 and 7*7**4==7**5 and 10**6*10**2*10==10**9"),
E('Même exposant',r"Écrire sous la forme d’une seule puissance : $2^4\times5^4$ ; $3^3\times(-2)^3$ ; $25^2\times4^2$.",r"On regroupe les facteurs par paires : $\res{10^4}$ ; $(3\times(-2))^3=\res{(-6)^3}$ ; $(25\times4)^2=100^2=\res{10^4}$.","Utiliser $a^n\times b^n=(ab)^n$.","assert 2**4*5**4==10**4 and 3**3*(-2)**3==(-6)**3 and 25**2*4**2==100**2==10**4"),
E('Justifier une règle',r"En écrivant les facteurs, expliquer pourquoi $4^3\times4^2=4^5$. L’égalité $4^3+4^2=4^5$ est-elle vraie ?",r"$4^3\times4^2=(4\times4\times4)\times(4\times4)$ contient cinq facteurs 4 : c’est $4^5$. En revanche $4^3+4^2=64+16=\res{80}$, alors que $4^5=1\,024$ : l’égalité est $\res{\text{fausse}}$. La règle concerne les produits.","Compter les facteurs ; calculer chaque membre pour une somme.","assert 4**3*4**2==4**5 and 4**3+4**2==80 and 4**5==1024"),
E('Calculer astucieusement',r"Calculer sans calculatrice $2^5\times5^5$ puis $8^3\times125^3$.",r"$2^5\times5^5=(2\times5)^5=10^5=\res{100\,000}$. De même $8^3\times125^3=(8\times125)^3=1\,000^3=\res{10^9}$, soit un milliard.","Regrouper des facteurs dont le produit est simple.","assert 2**5*5**5==10**5 and 8**3*125**3==1000**3==10**9"),
E('Une erreur à corriger',r"Lou écrit $3^2\times3^4=9^6$ et $2^3\times5^2=10^5$. Corriger chaque égalité.",r"Avec le même nombre 3, on additionne les exposants : $3^2\times3^4=3^6=\res{729}$, alors que $9^6=531\,441$. Pour $2^3\times5^2$, ni les bases ni les exposants ne sont égaux : on calcule $8\times25=\res{200}$.","Vérifier qu’une propriété s’applique avant de l’utiliser.","assert 3**2*3**4==3**6==729 and 9**6==531441 and 2**3*5**2==200"),
E('Une quantité qui double',r"Une quantité vaut 3 au départ et double à chaque étape. Exprimer sa valeur après six étapes avec une puissance, puis la calculer.",r"Chaque étape ajoute un facteur 2. Après six étapes : $3\times2^6=3\times64=\res{192}$. Le facteur initial 3 n’est pas la base de la puissance.","Distinguer valeur initiale et facteur répété.","assert 3*2**6==192"),
E('Un message transmis',r"Une personne envoie un message à 3 personnes : c’est l’étape 1. À chaque étape suivante, chaque nouveau destinataire l’envoie à 3 personnes qui ne l’ont pas encore reçu. Combien de personnes le reçoivent à l’étape 5 ? Combien de personnes connaissent le message après l’étape 5, l’expéditrice comprise ?",r"À l’étape $k$, le nombre de nouveaux destinataires est $3^k$. À l’étape 5 : $3^5=\res{243}$. Au total : $1+3+9+27+81+243=\res{364}$ personnes. On additionne ici des puissances : aucune règle ne les regroupe en une seule.","Associer chaque étape à un facteur 3.","assert 3**5==243 and sum(3**k for k in range(6))==364"),
E('Des fichiers',r"Une archive contient 2 400 images de 2,5 Mo chacune. On utilise les préfixes décimaux. Quelle taille totale en Mo, puis en Go et en octets ?",r"$2\,400\times2{,}5=\res{6\,000}$ Mo. Comme 1 Go = 1 000 Mo, le total vaut $\res6$ Go, soit $6\times10^9$ octets.","Choisir la même unité avant de multiplier.","assert 2400*Rational('2.5')==6000 and Rational(6000,1000)==6"),
E('Comparer de grandes distances',r"Une distance A vaut $4\times10^8$ m et une distance B vaut $35\times10^7$ m. Laquelle est la plus grande ? Écrire leur somme sous la forme $a\times10^8$ m.",r"$35\times10^7=3{,}5\times10^8$. Comme $4>3{,}5$, $\res{A}$ est la plus grande. La somme vaut $4\times10^8+3{,}5\times10^8=\res{7{,}5\times10^8}$ m : on additionne des multiples de la même puissance de 10.","Écrire les deux nombres avec la même puissance de 10.","assert 4*10**8>35*10**7 and 4*10**8+35*10**7==Rational('7.5')*10**8"),
E('Une somme à ne pas confondre',r"Calculer $A=3{,}2\times10^5+8\times10^4$, puis $B=3{,}2\times10^5\times8\times10^4$. Expliquer la différence.",r"Pour la somme, $8\times10^4=0{,}8\times10^5$, donc $A=\res{4\times10^5}$. Pour le produit, $3{,}2\times8=25{,}6$ et $10^5\times10^4=10^9$ : $B=25{,}6\times10^9=\res{2{,}56\times10^{10}}$. Une somme ne se traite pas comme un produit.","Identifier l’opération principale.","assert 320000+80000==400000 and 320000*80000==25600000000")
],reperes=['Définition et calcul d’une puissance','Puissances de dix et préfixes','Produits de puissances','Problèmes de répétition et grands nombres'],deco='calcul')
